  "politics.desc.concede": "Give them part of what they want. Calms the street at once; looks weak, and the hardliners will not forgive it.",
  "politics.desc.disperse": "The police clear the square. Stops a small protest; a big one comes back angrier. Police below 40 loyalty may refuse.",
  "politics.desc.troops": "Bring in the army. Ends almost anything – or ends you: soldiers below 40 loyalty may refuse to shoot or join the crowd.",
  "politics.act.arrestLeaders": "Arrest the organisers",
  "politics.desc.arrestLeaders": "Detain the people behind it. Beheads a weak protest; makes martyrs of a strong one.",
  "politics.order.arrestLeaders": "Arrest the organisers of «{title}»",
  "politics.act.counterRally": "Counter-rally",
  "politics.desc.counterRally": "Bus in supporters and hired muscle. Shows you have backers; clashes and provocations can turn the country against you.",
  "politics.order.counterRally": "Organise a counter-rally of supporters against «{title}»",
  "politics.act.curfew": "Curfew and a ban on rallies",
  "politics.desc.curfew": "Empties the streets for a while; breaking it becomes the protest.",
  "politics.order.curfew": "Impose a curfew and ban rallies where «{title}» is strongest",
  "politics.act.smearProtest": "Discredit on television",
  "politics.desc.smearProtest": "Television tells the country the protesters are paid agents and extremists. Works on your voters; enrages the rest.",
