  "politics.desc.campaign": "Rallies, posters and airtime for the party across the country. Its support grows if the times are with it.",
  "politics.act.renew": "Renew the leadership",
  "politics.desc.renew": "Replace the party's old guard with new faces. Refreshes its image; the ousted will hold a grudge.",
  "politics.order.renew": "Renew the leadership of «{party}»: replace the old guard with new faces",
  "politics.desc.support": "Money, airtime and access for the party. Its support grows; voters may call it the government's puppet.",
  "politics.act.negotiate": "Strike a deal",
  "politics.desc.negotiate": "Bargain for their votes on a specific question without a coalition. Cheaper than a coalition, but they set the price.",
  "politics.order.negotiate": "Negotiate with «{party}» for their votes in parliament",
  "politics.act.leave": "End the coalition",
  "politics.desc.leave": "Push the partner out of government. Frees your hands, but costs you their seats.",
  "politics.order.leave": "End the coalition with «{party}» and dismiss its ministers",
  "politics.act.coalition": "Invite into the coalition",
  "politics.desc.coalition": "Offer ministries and concessions for their votes. Their seats count for the government; their demands become yours.",
  "politics.order.coalition": "Invite «{party}» into the governing coalition: offer ministries and concessions for their votes",
  "politics.act.poach": "Poach deputies",
  "politics.desc.poach": "Win over their deputies with posts, money or pressure. Adds seats without an election; a scandal if it comes out.",
  "politics.order.poach": "Win over deputies of «{party}» to the government's side",
  "politics.act.smear": "Discredit",
  "politics.desc.smear": "Compromising material, scandals and hostile press against the party and its leader. Their support falls if it sticks.",
  "politics.order.smear": "Run a campaign to discredit «{party}» and its leader",
  "politics.desc.suppress": "Searches, pressure, arrests of activists. Weakens the party, radicalises its supporters and raises unrest.",
  "politics.act.arrest": "Arrest the leader",
  "politics.desc.arrest": "Prosecute the party's leader. Beheads the party, or makes a martyr.",
  "politics.order.arrest": "Arrest the leader of «{party}»",
  "politics.desc.ban": "Outlaw the party. It goes underground, its seats empty and its supporters take to the street.",
  "politics.desc.legalise": "Let the party back into legal politics. Calms its supporters; it will compete for votes.",
  "politics.act.secretTalks": "Secret talks",
  "politics.desc.secretTalks": "Make contact through go-betweens. Can bring the party out of the underground, or split it.",
