  "crisis.power.effect": "The plants cannot meet the demand for electricity: blackouts and rationed power, idle factories, cold and dark homes. Output falls and unrest rises until plants are built or their fuel comes back.",
  "energy.title": "Electricity",
  "energy.hint": "Power plants of seven kinds give the country its electricity. Coal, oil and gas plants burn the strategic resources it digs or imports, reactors burn uranium; a blockade or sanctions that cut the imports empty the stores and then darken the plants, and land the enemy holds takes its plants out of use. Demand grows with the economy. Plants are built from the industry line over the years each kind takes – by order, or by the industry minister – and a war destroys them. A shortage slows growth, darkens homes and angers people.",
