  "atom.title": "Atomic programme",
  "atom.hint": "A first reactor, the material for a bomb, a device, the first test, then the hydrogen bomb. The programme runs while strategic research gets at least {n}% of the money, and the more it gets the faster it goes. Once the country has tested, the stockpile grows by the army's plans, or as the orders set it. A nuclear power is far less likely to be attacked. Using the bomb is the gravest act there is, and only an order in so many words does it.",
