  "nuclear.title": "Nuclear red lines",
  "nuclear.hint": "Every atomic power the computer governs climbs a ladder at war – threats, a raised alert, a demonstration, a tactical strike at the front, a strike on cities – by how near defeat it sees itself: its capital, its heartland and land, its army, its regime, a nuclear strike on it. A cautious leader stops lower; an enemy that can answer and the era's taboo hold it back. Red lines: grey – far, orange – near, red – crossed.",
