  "guide.doIt": "Do it, and the guide moves on.",
  "guide.waiting": "The game master is writing the week…",
  "guide.welcome.title": "You lead Ukraine",
  "guide.welcome.body": "This is the tutorial. Each card asks you to do one thing and moves on when you have done it. The first two weeks need no account.",
  "guide.welcome.go": "Begin",
  "guide.map.title": "The map",
  "guide.map.body": "Ukraine is drawn in its colour, Russia in its own. Hatched land is held by someone other than its owner, a striped province is fought over, and the thick border between holders is the front. Click a country or a province to see it.",
  "guide.order.title": "Your first order",
  "guide.order.body": "Write what your government does this turn, in plain words: the game master works out what comes of it. Use this order or write your own, then press Add order.",
  "guide.end.title": "End the turn",
  "guide.end.body": "A turn here is one week. Press End turn: the week is played and its report opens.",
  "guide.report.title": "The report",
  "guide.report.body": "First the story of the week, then a verdict on each of your orders – done, partly done or failed – and what changed. When you have read it, go back to the game.",
  "guide.front.title": "The front moved",
  "guide.front.body": "The week's changes glow on the map: the Russians advanced in the north, the east and the south. The bar at the top shows your money, your army and the mood at home.",
  "guide.cabinet.title": "Your cabinet",
  "guide.cabinet.body": "Ministers advise you and carry out the work. Open the cabinet.",
  "guide.ask.title": "Ask a minister",
  "guide.ask.body": "Pick a minister and ask anything. Try asking the commander-in-chief:",
  "guide.army.title": "The army",
  "guide.army.body": "Soldiers, weapons and where they fight. Open the army.",
  "guide.economy.title": "The economy",
  "guide.economy.body": "The budget, the resources and the trade that pay for the war. Open the economy.",
  "guide.letter.title": "Write to a government",
  "guide.letter.body": "Letters go to any government, and each answers in its own voice. Write to Poland, for example:",
  "guide.free.title": "Now play on your own",
  "guide.free.body": "That is the whole game: orders, the turn, the report, your ministers and the world. One more week is written in advance: write any orders and end the turn. For example:",
  "guide.free.go": "Play on",
  "guide.choose.title": "Who plays the world now?",
  "guide.choose.body": "The written weeks are over. Sign in with ChatGPT for the real game master on your own plan, or keep playing with the offline game master.",
  "guide.choose.demo": "Keep playing offline",
  "guide.choose.demoNote": "Simplified: an offline stand-in plays the world, so little really changes.",
  "guide.done.title": "You are ready",
  "guide.done.chatgpt": "The real game master plays the world from here, on your ChatGPT plan. Good luck.",
  "guide.done.demo": "The offline game master plays from here: simplified, but enough to learn the game. Sign in with ChatGPT in Settings whenever you like.",
  "guide.finish": "Finish the tutorial",
  "state.quick.1": "I want to rename the country. Let's talk about a name.",
  "state.quick.2": "Which city deserves a new name, and how will people take it?",
  "state.quick.3": "Which law holds us back most right now? Draft a change.",
  "law.conscription.about": "Who serves in the army: volunteers on contract, some of each year's young men, or every one of them. More conscripts mean a bigger army and more resentment.",
  "law.martial.about": "Normal rule, a state of emergency or martial law: how far the government may suspend rights, take property and rule by order.",
  "law.press.about": "How free newspapers, radio and television are, from free to run by the state.",
  "law.assembly.about": "Whether people may gather and march: freely, with a permit, or not at all.",
  "law.elections.about": "How power changes hands: free elections, managed ones, or none.",
  "law.economy.about": "Who runs the economy: the market, the state and the market together, or the plan.",
  "law.language.about": "The language of the state, schools and courts: one, regional languages beside it, or two equal ones.",
  "law.alignment.about": "The country's place among the blocs: neutral, non-aligned, or in an alliance.",
  "law.deathPenalty.about": "Whether courts may sentence people to death.",
  "law.exit.about": "Whether citizens may leave the country: freely, with a permit, or not at all.",
