  "portraits.title": "Портреты",
  "portraits.about": "Лидеры и министры, а также писатели и мыслители, которых цитирует ожидание хода, написаны маслом по изображениям со свободной лицензией: общественное достояние, CC0, CC BY, CC BY-SA, открытые лицензии правительств Великобритании, Индии и Кореи и Европарламента, Free Art License, либо без известных ограничений авторского права, из Wikimedia Commons. Портрет сохраняет лицензию своей фотографии, отдельно от кода игры под AGPL-3.0. У кого свободной фотографии нет, и у любого нового человека – силуэт.",
