  "scenes.title": "Картины дат",
  "scenes.about": "Двенадцать дат на главной написаны маслом по свободным снимкам своего момента из Wikimedia Commons: общественное достояние, CC BY или CC BY-SA. Каждая картина сохраняет лицензию своего снимка, отдельно от кода игры под AGPL-3.0.",
  "scenes.show": "Показать авторов снимков",
  "quotes.title": "Цитаты",
  "quotes.about": "У цитат, которые показываются, пока пишется ход, – государственные деятели игры рядом с писателями, мыслителями и мудрецами всех веков – есть источник и дата. Большинство взято из подтверждённых строк Викицитатника (CC BY-SA 4.0) и переведено на русский, украинский и английский; его страницы перечислены здесь.",
