  "econ.hint.other": "Управление, полиция, суды, дороги и содержание государства. Ниже обычных {n}% ВВП (не меньше седьмой части доходов) государство за несколько месяцев приходит в упадок – страдают рост, порядок и жильё, тем сильнее, чем глубже и дольше урезано, – и восстанавливается, когда статью возвращают; сверх нормы почти ничего не даёт.",
