  "supply.why.upkeep": "Статья «Прочее» ниже обычной доли: не оплачены жилищные службы, коммунальное хозяйство и ремонт. Если её вернуть, за несколько месяцев всё наладится.",
  "supply.why.warEconomy": "[[armyBudget|Армия]] забирает больше 8% ВВП: каждый пункт сверх отнимает полтора пункта товаров у населения. Вложения в промышленность, политики и импорт за несколько месяцев вернут до трёх пятых; всё вернёт только меньший военный бюджет.",
  "supply.why.austerity": "[[socialBudget|Соцрасходы]] ниже обычной для эпохи доли ВВП: не хватает жилья и больниц. Их вернёт рост социальной статьи.",
  "supply.cause.mobilisation": "мобилизация",
  "supply.why.mobilisation": "Мужчин, надолго оставленных под ружьём, не хватает на заводах и в полях: товаров и еды тем меньше, чем дольше это длится и чем больше их гибнет. Отпуск по домам всё возвращает.",
  "supply.cause.research": "исследования",
  "supply.cause.industry": "вложения в промышленность",
  "supply.why.industry": "[[industryBudget|Расходы на промышленность]] сверх обычной для эпохи доли ВВП за несколько месяцев строят фабрики товаров и поднимают добычу, как и политики развития промышленности и инфраструктуры; расходы ниже нормы их сокращают. Деньги идут из бюджета, как любая статья.",
  "supply.why.imports": "Товары и топливо, купленные за границей, пока торговля открыта. Товары оплачиваются из [[reserves|резервов]] и прекращаются, когда резервы подходят к половине обычного для эпохи уровня.",
  "supply.hint.goods": "Что поднимает товары: меньший [[armyBudget|военный бюджет]]; [[industryBudget|расходы на промышленность]] сверх обычной для эпохи доли и политики развития промышленности или инфраструктуры (строятся месяцами); опережение в промышленных [[research|исследованиях]]; импорт, пока торговля открыта и хватает [[reserves|резервов]].",
  "supply.hint.energy": "Что поднимает энергию и запасы: своя добыча сверх потребности пополняет запасы; [[industryBudget|расходы на промышленность]], политики развития промышленности и инфраструктуры и опережение в промышленных [[research|исследованиях]] за десятилетие дают до 30% больше добычи; контракты пополняют запасы того, что везут.",
