  "ministry.close.title": "Упразднить «{name}»?",
  "ministry.close.body": "{name} уходит из правительства; замы министерства, их интриги и его директивы уходят вместе с ним, а работа переходит к главе администрации. Следующий ход покажет, чем это обернётся: сокращения, освободившиеся деньги, передел полномочий. Упразднённое министерство можно восстановить.",
  "ministry.close.bodyVacant": "Замы министерства, их интриги и его директивы уходят; работа переходит к главе администрации. Следующий ход покажет, чем это обернётся. Упразднённое министерство можно восстановить.",
