  "resolution.sanctionsHint": "Проголосовавшие «за» вводят [[sanctions|санкции]] против нападающего.",
  "resolution.actionHint": "Члены, у которых есть силы, призваны на сторону жертвы: их шансы вступить в войну растут.",
  "resolution.councilHint": "[[securityCouncil|Совет Безопасности]]: пять постоянных членов с правом [[veto|вето]] и сильнейшие из остальных; решают семь голосов из одиннадцати (с 1966 года – девять из пятнадцати).",
  "resolution.assemblyHint": "Генеральная Ассамблея: голосуют все члены; решают две трети голосующих, но не меньше трети членов. С ноября 1950 года ([[unitingForPeace|«Единство в пользу мира»]]) она берётся за то, что блокирует [[veto|вето]].",
  "resolution.leagueHint": "Лига Наций: решают две трети; напавшего члена исключают, [[sanctions|санкциям]] члены следуют вполсилы, к оружию она не призывает.",
  "response.title": "Ответ мира",
  "response.gravity": "Тяжесть {n} из 3",
  "response.gravityHint": "Насколько тяжким мир счёл нападение: норма эпохи против завоеваний, вес нападающего против веса жертвы и другие его нападения за год.",
  "response.repeat": "нападений за год: {n}",
  "response.condemned": "Осудили",
  "response.condemnedHint": "Правительства, осудившие нападение: их доверие к нападающему упало – сильнее всего у тех, кому он угрожает, и у тех, кто стоит за жертвой.",
  "response.sanctions": "Санкции",
  "response.sanctionsHint": "[[sanctions|Санкции]] против нападающего после нападения – введённые и готовящиеся: соперников и демократий, а также членов, откликнувшихся на призыв международной организации.",
  "response.aid": "Оружие",
  "response.aidHint": "Правительства, которые поставляют жертве оружие из своих запасов, пока идёт война; они считаются её сторонниками.",
  "response.joining": "Могут вступить в войну",
  "response.joiningHint": "Правительства, взвешивающие вступление на стороне жертвы: [[bloc|союзники]] и [[pledge|гаранты]] – по договору, другие – по призыву международной организации; каждое – по своим силам, расстоянию и положению дома.",
  "response.pledges": "Гарантии",
  "response.pledgesHint": "Великие державы, после этого нападения [[pledge|пообещавшие защищать страну]]: нападение на неё теперь призовёт их по договору.",
