  "crisis.power": "Нехватка электричества ({value}%)",
  "crisis.power.effect": "Электростанции не покрывают спрос: веерные отключения и лимиты, заводы простаивают, в домах холодно и темно. Выпуск падает, недовольство растёт, пока не построят станции или не вернётся топливо.",
  "energy.title": "Электроэнергия",
  "energy.hint": "Электростанции семи видов дают стране электричество. Угольные, мазутные и газовые сжигают стратегические ресурсы, которые страна добывает или ввозит, реакторы – уран; блокада или санкции, отрезавшие импорт, опустошают запасы, а затем гасят станции, а земля, занятая врагом, выводит из строя её станции. Спрос растёт вместе с экономикой. Станции строятся из статьи «Промышленность» столько лет, сколько нужно каждому виду, – по приказу или силами министра промышленности, – а война их разрушает. Нехватка замедляет рост, гасит свет в домах и злит людей.",
