  "atom.title": "Атомная программа",
  "atom.hint": "Первый реактор, материал для бомбы, устройство, первое испытание, затем водородная бомба. Программа идёт, пока стратегические исследования получают не меньше {n}% денег, и чем больше, тем быстрее. После испытания запас растёт по планам армии или как прикажет правительство. На ядерную державу нападают куда реже. Применить бомбу – тягчайший шаг из возможных, и сделать это может только прямой приказ.",
