  "nuclear.title": "Ядерные красные линии",
  "nuclear.hint": "Каждая ядерная держава под управлением компьютера на войне поднимается по лестнице – угрозы, повышенная готовность, демонстрация, тактический удар по фронту, удар по городам – смотря по тому, насколько близко она видит поражение: столица, сердце страны и её земля, армия, режим, ядерный удар по ней. Осторожный лидер останавливается ниже; удерживают и противник, способный ответить, и табу эпохи. Красные линии: серая – далеко, оранжевая – близко, красная – пересечена.",
