  "demo.banner": "Демо: ведущий – офлайн-заглушка, ходы почти ничего не меняют, и ничего не сохраняется. Чтобы играть по-настоящему, запустите игру у себя с подпиской ChatGPT.",
  "download.windows": "Скачать для Windows",
