  "download.storeShort": "Microsoft Store",
  "download.installer": "Установщик с GitHub",
  "download.why": "Полная игра – в приложении: настоящий ведущий на вашей подписке ChatGPT, и партии сохраняются.",
  "demo.gone": "Это была демо-партия: демо ничего не сохраняет, и после перезагрузки страницы её нет. Начните новую или скачайте игру – в ней партии сохраняются.",
  "demo.chip": "Демо",
  "demo.try": "Попробовать демо",
  "demo.tryBody": "Мир играет упрощённый офлайн-ведущий. По-настоящему ничего не моделируется – войдите через ChatGPT, чтобы играл настоящий ведущий.",
  "demo.play": "Играть в демо",
