  "scenes.title": "Картини дат",
  "scenes.about": "Дванадцять дат на головній намальовано олією за вільними знімками свого моменту з Wikimedia Commons: суспільне надбання, CC BY або CC BY-SA. Кожна картина зберігає ліцензію свого знімка, окремо від коду гри під AGPL-3.0.",
  "scenes.show": "Показати авторів знімків",
  "quotes.title": "Цитати",
