  "econ.hint.revenue": "Податки та інші доходи держави. Понад {n}% ВВП починають гальмувати зростання.",
  "econ.hint.army": "Платня, постачання й зброя армії; п'ята частина йде на військові дослідження. Понад 8% ВВП забирає товари в населення.",
  "econ.hint.industry": "Заводи, дороги й енергетика, три десятих – на дослідження. Понад звичні для епохи {n}% ВВП прискорює зростання (кожне подвоєння дає менше), а за кілька місяців – товари в крамницях і видобуток ресурсів; нижче – знижує їх.",
  "econ.hint.social": "Школи, лікарні, пенсії та житло. Нижче звичних для епохи {n}% ВВП страждають житло й медицина.",
  "econ.hint.other": "Управління, поліція, суди, дороги й утримання держави. Нижче звичних {n}% ВВП (не менше сьомої частини доходів) держава за кілька місяців занепадає – страждають зростання, порядок і житло, тим сильніше, чим глибше й довше урізано, – і відновлюється, коли статтю повертають; понад норму майже нічого не дає.",
  "econ.hint.otherCabinet": "До неї входить кабінет, як він є: створено міністерств – {created} (кожне +2%), скасовано – {closed} (кожне −1,5%).",
