  "supply.why.upkeep": "Стаття «Інше» нижча за звичну частку: не оплачені житлові служби, комунальне господарство й ремонт. Якщо її повернути, за кілька місяців усе налагодиться.",
  "supply.why.warEconomy": "[[armyBudget|Армія]] забирає понад 8% ВВП: кожен пункт понад це відбирає півтора пункту товарів у населення. Вкладення в промисловість, політики й імпорт за кілька місяців повернуть до трьох п'ятих; усе поверне лише менший військовий бюджет.",
  "supply.why.austerity": "[[socialBudget|Соцвидатки]] нижчі за звичну для епохи частку ВВП: бракує житла й лікарень. Їх поверне більша соціальна стаття.",
  "supply.cause.mobilisation": "мобілізація",
  "supply.why.mobilisation": "Чоловіків, надовго залишених під зброєю, бракує на заводах і в полях: товарів та їжі тим менше, чим довше це триває і чим більше їх гине. Відпустка додому все повертає.",
