  "supply.why.industry": "[[industryBudget|Видатки на промисловість]] понад звичну для епохи частку ВВП за кілька місяців будують фабрики товарів і піднімають видобуток, як і політики розвитку промисловості та інфраструктури; видатки нижчі за норму їх скорочують. Гроші йдуть із бюджету, як будь-яка стаття.",
  "supply.why.imports": "Товари й паливо, куплені за кордоном, поки торгівля відкрита. Товари оплачуються з [[reserves|резервів]] і припиняються, коли резерви підходять до половини звичного для епохи рівня.",
  "supply.hint.goods": "Що піднімає товари: менший [[armyBudget|військовий бюджет]]; [[industryBudget|видатки на промисловість]] понад звичну для епохи частку й політики розвитку промисловості чи інфраструктури (будуються місяцями); випередження в промислових [[research|дослідженнях]]; імпорт, поки торгівля відкрита й вистачає [[reserves|резервів]].",
  "supply.hint.energy": "Що піднімає енергію й запаси: власний видобуток понад потребу поповнює запаси; [[industryBudget|видатки на промисловість]], політики розвитку промисловості й інфраструктури та випередження в промислових [[research|дослідженнях]] за десятиліття дають до 30% більше видобутку; контракти поповнюють запаси того, що везуть.",
