  "ministry.close.title": "Скасувати «{name}»?",
  "ministry.close.body": "{name} іде з уряду; заступники міністерства, їхні інтриги та його директиви йдуть разом із ним, а робота переходить до глави адміністрації. Наступний хід покаже, чим це обернеться: скорочення, вивільнені гроші, переділ повноважень. Скасоване міністерство можна відновити.",
