  "crisis.power.effect": "Електростанції не покривають попиту: віялові відключення й ліміти, заводи стоять, у домівках холодно й темно. Випуск падає, невдоволення росте, доки не збудують станції або не повернеться паливо.",
  "energy.title": "Електроенергія",
  "energy.hint": "Електростанції семи видів дають країні електрику. Вугільні, мазутні й газові спалюють стратегічні ресурси, які країна видобуває чи ввозить, реактори – уран; блокада чи санкції, що відрізали імпорт, спорожнюють запаси, а тоді гасять станції, а земля, яку тримає ворог, виводить з ладу її станції. Попит росте разом з економікою. Станції будуються зі статті «Промисловість» стільки років, скільки треба кожному виду, – за наказом або силами міністра промисловості, – а війна їх руйнує. Брак уповільнює зростання, гасить світло в домівках і злить людей.",
