  "atom.hint": "Перший реактор, матеріал для бомби, пристрій, перше випробування, тоді воднева бомба. Програма йде, доки стратегічні дослідження отримують щонайменше {n}% грошей, і що більше, то швидше. Після випробування запас росте за планами армії або як накаже уряд. На ядерну державу нападають значно рідше. Застосувати бомбу – найтяжчий крок з можливих, і зробити це може тільки прямий наказ.",
