  "nuclear.title": "Ядерні червоні лінії",
  "nuclear.hint": "Кожна ядерна держава під керуванням комп'ютера на війні піднімається драбиною – погрози, підвищена готовність, демонстрація, тактичний удар по фронту, удар по містах – залежно від того, наскільки близько вона бачить поразку: столиця, серце країни та її земля, армія, режим, ядерний удар по ній. Обережний лідер зупиняється нижче; стримують і супротивник, здатний відповісти, і табу доби. Червоні лінії: сіра – далеко, помаранчева – близько, червона – перетнута.",
