  "cabinet.purge.title": "Чистка: {faction}?",
  "cabinet.purge.body": "{names} підуть – у відставку там, де вирішують вибори, під арешт в інших випадках, – а з ними й більшість їхніх заступників. Еліти й спецслужби здригнуться, невдоволення зросте, виборці в демократії відвернуться, а решта кабінету боятиметься, що наступна – вона. Якщо розвідка вказала не на тих, справжні змовники залишаться.",
